svg.script:
(function () {
  var f = document.getElementById('mp');
  var st = document.getElementById('st');
  var st2 = document.getElementById('st2');
  var base = location.href.replace(/[#?][\s\S]*$/, '').replace(/[^\/]*$/, '');
  var target = base + 'index.html';
  var pending = location.hash;
  var loaded = false, watch;

  function say(m){ st.textContent = m; }
  function err(m){ st2.textContent = m; console.error('[moplite]', m); }

  function sync() {
    try {
      var w = f.contentWindow, d = w.document;
      if (d.URL === 'about:blank' || !d.body) return;
      loaded = true; clearTimeout(watch);
      f.style.background = '#07070a';
      if (pending && d.location.hash !== pending) d.location.hash = pending;
      pending = '';
      w.addEventListener('hashchange', function () {
        try { history.replaceState(null, '', d.location.hash || '#/'); } catch (e) {}
      });
      if (window.MutationObserver) {
        new MutationObserver(function () {
          if (d.title && document.title !== d.title) document.title = d.title;
        }).observe(d.documentElement, { childList: true, subtree: true, characterData: true });
      }
      if (d.title) document.title = d.title;
    } catch (e) { err('sync: ' + e.message); }
  }

  f.addEventListener('load', sync);
  addEventListener('hashchange', function () {
    try { var w = f.contentWindow; if (w && w.location.hash !== location.hash) w.location.hash = location.hash; }
    catch (e) {}
  });

  function direct() {
    say('direct iframe (last resort)');
    f.removeAttribute('srcdoc');
    f.src = target;
  }

  function fallback(reason) {
    err(reason);
    say('trying srcdoc…');
    fetch(target, { cache: 'no-cache', credentials: 'omit' })
      .then(function (r) { return r.text(); })
      .then(function (h) {
        if (!/<base\s/i.test(h)) h = h.replace(/<head([^>]*)>/i, '<head$1><base href="' + base + '">');
        f.setAttribute('srcdoc', h);
        setTimeout(function () { if (!loaded) direct(); }, 3000);
      })
      .catch(function () { direct(); });
  }

  watch = setTimeout(function () {
    if (!loaded) err('watchdog: nothing rendered after 9s');
  }, 9000);

  say('fetching index.html');
  try {
    fetch(target, { cache: 'no-cache', credentials: 'omit' })
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status + ' for ' + target);
        return r.text();
      })
      .then(function (h) {
        if (h.length < 200) throw new Error('index.html looks empty (' + h.length + ' bytes)');
        say('got ' + h.length + ' bytes, building frame');
        if (!/<base\s/i.test(h)) h = h.replace(/<head([^>]*)>/i, '<head$1><base href="' + base + '">');
        f.src = URL.createObjectURL(new Blob([h], { type: 'text/html' }));
      })
      .catch(function (e) { fallback('blob path failed: ' + e.message); });
  } catch (e) { fallback('throw: ' + e.message); }

  if ('serviceWorker' in navigator && location.protocol === 'https:') {
    navigator.serviceWorker.register(base + 'sw.js').catch(function () {});
  }
})();
